const deps = {
  Web: ['API'],
  API: ['DB'],
  DB: []
};
function canReach(from, to, seen = []) {
  if (from === to) return true;
  if (seen.includes(from)) return false;
  return deps[from].some(d => canReach(d, to, [...seen, from]));
}
console.log(canReach('Web', 'DB'));

